=== FILE: skid_buffer.v ===
`timescale 1ns/1ps
// skid_buffer: register slice for one valid/ready stream.
// Implements microarchitecture.md (state table section 2, next-state table
// section 3) for interface_spec.md. Every output is a flop or the inverse of
// one; inputs reach only next-state logic.
module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    // Skid register: holds the newer of two beats.
    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // Upstream ready is the inverse of a flop.
    assign s_ready = ~skid_valid;

    // The output register may load on this edge.
    wire m_free;
    assign m_free = (~m_valid) | m_ready;

    // An upstream beat is accepted on this edge.
    wire s_fire;
    assign s_fire = s_valid & (~skid_valid);

    // Next-state logic (microarchitecture section 3).
    reg m_valid_d;
    reg skid_valid_d;
    reg m_load;
    reg skid_load;

    always @* begin
        m_valid_d    = m_valid;
        skid_valid_d = skid_valid;
        m_load       = 1'b0;
        skid_load    = 1'b0;
        if (m_free) begin
            // Load the skid beat if one is held, else the input beat.
            m_valid_d    = skid_valid | s_valid;
            skid_valid_d = 1'b0;
            m_load       = 1'b1;
        end else if (s_fire) begin
            // Output stalled: catch the accepted beat in the skid register.
            skid_valid_d = 1'b1;
            skid_load    = 1'b1;
        end
    end

    wire [WIDTH-1:0] m_data_d;
    assign m_data_d = skid_valid ? skid_data : s_data;

    // Control registers: synchronous active-low reset drops every beat.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else begin
            m_valid    <= m_valid_d;
            skid_valid <= skid_valid_d;
        end
    end

    // Data registers: not reset; each loads only in its control's row.
    always @(posedge clk) begin
        if (m_load) begin
            m_data <= m_data_d;
        end
    end

    always @(posedge clk) begin
        if (skid_load) begin
            skid_data <= s_data;
        end
    end

endmodule
=== END FILE ===
