`timescale 1ns/1ps
// Self-checking testbench for skid_buffer (interface_spec.md section 6).
// Two lanes, WIDTH 8 and WIDTH 1, share control inputs; the WIDTH 1 lane
// carries bit 0 of the WIDTH 8 data. A queue model of up to two beats is
// checked every cycle.
module skid_buffer_tb;

    reg        clk;
    reg        rst_n;
    reg        s_valid;
    reg        m_ready;
    reg  [7:0] s_data8;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire       m_data1;

    skid_buffer #(.WIDTH(8)) dut8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready8),
        .s_data  (s_data8),
        .m_valid (m_valid8),
        .m_ready (m_ready),
        .m_data  (m_data8)
    );

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready1),
        .s_data  (s_data8[0]),
        .m_valid (m_valid1),
        .m_ready (m_ready),
        .m_data  (m_data1)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;

    integer passed;
    integer failed;
    integer count;
    integer beats_in;
    integer beats_out;
    integer beats_dropped;
    integer seed;
    integer r;
    integer i;
    integer j;
    integer k;
    integer rc;
    reg     known;
    reg     hold_pending;
    reg     mr_v;
    reg [7:0] q0;
    reg [7:0] q1;
    reg [7:0] hold_d8;
    reg [8*64-1:0] nonce;

    // Record one check.
    task chk;
        input         cond;
        input integer id;
        begin
            if (cond) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("skid_buffer_tb: check %0d failed at %0t", id, $time);
            end
        end
    endtask

    // Compare both lanes' outputs with the model.
    task check_outputs;
        begin
            chk(m_valid8 === (count > 0), 1);
            chk(m_valid1 === (count > 0), 2);
            chk(s_ready8 === (count < 2), 3);
            chk(s_ready1 === (count < 2), 4);
            if (count > 0) begin
                chk(m_data8 === q0, 5);
                chk(m_data1 === q0[0], 6);
            end
            if (hold_pending) begin
                chk((m_valid8 === 1'b1) && (m_data8 === hold_d8), 7);
                chk((m_valid1 === 1'b1) && (m_data1 === hold_d8[0]), 8);
            end
        end
    endtask

    // One clock cycle: drive the inputs at the negedge, check the outputs,
    // flip the inputs inside the cycle to show the outputs do not follow
    // them, then take the posedge and update the model.
    task cycle;
        input       rst_in;
        input       sv;
        input [7:0] sd;
        input       mr;
        reg       sr8_b;
        reg       sr1_b;
        reg       mv8_b;
        reg       mv1_b;
        reg [7:0] md8_b;
        reg       md1_b;
        reg       s_fire_m;
        reg       m_fire_m;
        begin
            @(negedge clk);
            rst_n   = rst_in;
            s_valid = sv;
            s_data8 = sd;
            m_ready = mr;
            #1;
            if (known) begin
                check_outputs;
                sr8_b = s_ready8;
                sr1_b = s_ready1;
                mv8_b = m_valid8;
                mv1_b = m_valid1;
                md8_b = m_data8;
                md1_b = m_data1;
                s_valid = ~sv;
                m_ready = ~mr;
                s_data8 = ~sd;
                #1;
                chk((s_ready8 === sr8_b) && (s_ready1 === sr1_b), 9);
                chk((m_valid8 === mv8_b) && (m_data8 === md8_b), 10);
                chk((m_valid1 === mv1_b) && (m_data1 === md1_b), 11);
                s_valid = sv;
                m_ready = mr;
                s_data8 = sd;
                #1;
            end
            s_fire_m = sv && (count < 2);
            m_fire_m = mr && (count > 0);
            @(posedge clk);
            if (!rst_in) begin
                if (known) begin
                    beats_dropped = beats_dropped + count;
                end
                count        = 0;
                known        = 1'b1;
                hold_pending = 1'b0;
            end else if (known) begin
                hold_pending = (count > 0) && !mr;
                hold_d8      = q0;
                if (m_fire_m) begin
                    beats_out = beats_out + 1;
                    q0        = q1;
                    count     = count - 1;
                end
                if (s_fire_m) begin
                    beats_in = beats_in + 1;
                    if (count == 0) begin
                        q0 = sd;
                    end else begin
                        q1 = sd;
                    end
                    count = count + 1;
                end
            end
        end
    endtask

    initial begin
        passed        = 0;
        failed        = 0;
        count         = 0;
        beats_in      = 0;
        beats_out     = 0;
        beats_dropped = 0;
        known         = 1'b0;
        hold_pending  = 1'b0;
        mr_v          = 1'b0;
        q0            = 8'h00;
        q1            = 8'h00;
        hold_d8       = 8'h00;
        seed          = 32'h1f2e3d4c;
        rst_n         = 1'b0;
        s_valid       = 1'b0;
        m_ready       = 1'b0;
        s_data8       = 8'h00;
        nonce         = {(8*64){1'b0}};
        rc = $value$plusargs("nirmaan_nonce=%s", nonce);

        // 1. Reset values.
        cycle(1'b0, 1'b0, 8'h00, 1'b0);
        cycle(1'b0, 1'b1, 8'h55, 1'b1);
        #1;
        chk((m_valid8 === 1'b0) && (m_valid1 === 1'b0), 100);
        chk((s_ready8 === 1'b1) && (s_ready1 === 1'b1), 101);

        // 2. One-cycle latency: accepted on edge E, offered after E.
        cycle(1'b1, 1'b1, 8'hA1, 1'b0);
        #1;
        chk((m_valid8 === 1'b1) && (m_data8 === 8'hA1), 110);
        chk((m_valid1 === 1'b1) && (m_data1 === 1'b1), 111);
        cycle(1'b1, 1'b0, 8'h00, 1'b1);
        #1;
        chk((m_valid8 === 1'b0) && (m_valid1 === 1'b0), 112);

        // 3. Full throughput: one beat in and one out on every edge.
        j = beats_out;
        k = beats_in;
        for (i = 0; i < 32; i = i + 1) begin
            cycle(1'b1, 1'b1, (i[7:0] + 8'h10), 1'b1);
            #1;
            chk((m_valid8 === 1'b1) && (m_data8 === (i[7:0] + 8'h10)), 120);
            chk((m_valid1 === 1'b1) && (m_data1 === i[0]), 121);
            chk((s_ready8 === 1'b1) && (s_ready1 === 1'b1), 122);
        end
        chk((beats_out - j) == 31, 123);
        chk((beats_in - k) == 32, 124);
        cycle(1'b1, 1'b0, 8'h00, 1'b1);
        #1;
        chk((m_valid8 === 1'b0) && (m_valid1 === 1'b0), 125);

        // 4. Stall: with one beat held a second is accepted; with two a
        //    third is not. Then ready rises and the beats leave in order.
        cycle(1'b1, 1'b1, 8'hB0, 1'b0);
        #1;
        chk((m_valid8 === 1'b1) && (m_data8 === 8'hB0) && (s_ready8 === 1'b1), 130);
        cycle(1'b1, 1'b1, 8'hB1, 1'b0);
        #1;
        chk((s_ready8 === 1'b0) && (s_ready1 === 1'b0) && (m_data8 === 8'hB0), 131);
        cycle(1'b1, 1'b1, 8'hB2, 1'b0);
        #1;
        chk((s_ready8 === 1'b0) && (m_valid8 === 1'b1) && (m_data8 === 8'hB0), 132);
        for (i = 0; i < 4; i = i + 1) begin
            cycle(1'b1, 1'b1, (i[7:0] + 8'hC0), 1'b0);
            #1;
            chk((s_ready8 === 1'b0) && (m_valid8 === 1'b1) && (m_data8 === 8'hB0), 133);
        end
        cycle(1'b1, 1'b1, 8'hB2, 1'b1);
        #1;
        chk((m_valid8 === 1'b1) && (m_data8 === 8'hB1) && (s_ready8 === 1'b1), 134);
        cycle(1'b1, 1'b1, 8'hB2, 1'b1);
        #1;
        chk((m_valid8 === 1'b1) && (m_data8 === 8'hB2) && (s_ready8 === 1'b1), 135);
        cycle(1'b1, 1'b0, 8'h00, 1'b1);
        #1;
        chk((m_valid8 === 1'b0) && (m_valid1 === 1'b0), 136);

        // 5. Stream with ready low for one cycle and for several.
        for (i = 0; i < 48; i = i + 1) begin
            mr_v = !((i == 5) || ((i >= 12) && (i < 17)) || (i == 20) ||
                     (i == 22) || ((i >= 30) && (i < 38)));
            cycle(1'b1, 1'b1, i[7:0], mr_v);
        end
        for (i = 0; i < 3; i = i + 1) begin
            cycle(1'b1, 1'b0, 8'h00, 1'b1);
        end
        #1;
        chk((count == 0) && (m_valid8 === 1'b0) && (s_ready8 === 1'b1), 137);

        // 6. Random traffic against the model, ending in a drain.
        for (i = 0; i < 3000; i = i + 1) begin
            r = $random(seed);
            if (i < 1500) begin
                cycle(1'b1, (r[0] | r[1]), r[15:8], r[2]);
            end else begin
                cycle(1'b1, r[0], r[15:8], (r[2] | r[3]));
            end
        end
        for (i = 0; i < 4; i = i + 1) begin
            cycle(1'b1, 1'b0, 8'h00, 1'b1);
        end
        #1;
        chk((count == 0) && (m_valid8 === 1'b0) && (m_valid1 === 1'b0), 140);
        chk((s_ready8 === 1'b1) && (s_ready1 === 1'b1), 141);

        // 7. Reset with two beats held.
        cycle(1'b1, 1'b1, 8'hD0, 1'b0);
        cycle(1'b1, 1'b1, 8'hD1, 1'b0);
        #1;
        chk((m_valid8 === 1'b1) && (s_ready8 === 1'b0) && (s_ready1 === 1'b0), 150);
        cycle(1'b0, 1'b1, 8'hD2, 1'b0);
        #1;
        chk((m_valid8 === 1'b0) && (m_valid1 === 1'b0), 151);
        chk((s_ready8 === 1'b1) && (s_ready1 === 1'b1), 152);
        cycle(1'b1, 1'b1, 8'hD3, 1'b1);
        #1;
        chk((m_valid8 === 1'b1) && (m_data8 === 8'hD3), 153);
        cycle(1'b1, 1'b0, 8'h00, 1'b1);
        #1;
        chk((m_valid8 === 1'b0) && (m_valid1 === 1'b0), 154);

        // 8. Random traffic with reset during traffic.
        for (i = 0; i < 1500; i = i + 1) begin
            r = $random(seed);
            cycle((r[11:6] != 6'd0), (r[0] | r[1]), r[23:16], (r[2] | r[3]));
        end
        for (i = 0; i < 4; i = i + 1) begin
            cycle(1'b1, 1'b0, 8'h00, 1'b1);
        end
        #1;
        chk((count == 0) && (m_valid8 === 1'b0) && (s_ready8 === 1'b1), 160);

        // Every accepted beat left exactly once or was dropped by reset.
        chk(beats_in == (beats_out + beats_dropped), 170);
        chk(beats_out > 0, 171);
        chk(beats_dropped > 0, 172);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
